<?php
$schedules=$db->query("SELECT s.id,s.schedule_date,s.start_time,sub.name subject_name,c.name class_name,s.material_id FROM schedules s JOIN subjects sub ON sub.id=s.subject_id JOIN classes c ON c.id=s.class_id ORDER BY s.schedule_date DESC,s.start_time DESC LIMIT 250")->fetchAll();$materials=$db->query('SELECT id,title FROM materials ORDER BY title')->fetchAll();
$edit=null;if(isset($_GET['edit'])){$stmt=$db->prepare('SELECT * FROM teaching_journals WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch();}$showForm=isset($_GET['create'])||$edit;
$journals=$db->query("SELECT j.*,s.schedule_date,s.start_time,sub.name subject_name,c.name class_name,m.title material_title FROM teaching_journals j JOIN schedules s ON s.id=j.schedule_id JOIN subjects sub ON sub.id=s.subject_id JOIN classes c ON c.id=s.class_id LEFT JOIN materials m ON m.id=j.material_id ORDER BY s.schedule_date DESC,j.created_at DESC")->fetchAll();
?>
<div class="section-title"><div><h2>Jurnal pelaksanaan</h2><p>Bandingkan rencana mengajar dengan pelaksanaan sebenarnya.</p></div><a class="btn btn-primary" href="<?= url('journals',['create'=>1]) ?>"><?= icon('plus',17) ?> Isi jurnal</a></div>
<?php if($showForm): ?><section class="card"><div class="card-header"><div><h2><?= $edit?'Edit':'Tambah' ?> jurnal mengajar</h2></div></div><div class="card-body"><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_journal"><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>"><div class="form-grid"><div class="form-group full"><label>Jadwal *</label><select class="form-control" name="schedule_id" required><option value="">Pilih jadwal</option><?php foreach($schedules as $item): ?><option value="<?= $item['id'] ?>" <?= selected($edit['schedule_id']??'', $item['id']) ?>><?= e(format_date($item['schedule_date']).' '.substr($item['start_time'],0,5).' • '.$item['subject_name'].' • '.$item['class_name']) ?></option><?php endforeach; ?></select></div><div class="form-group full"><label>Materi referensi</label><select class="form-control" name="material_id"><option value="">Tanpa materi terhubung</option><?php foreach($materials as $item): ?><option value="<?= $item['id'] ?>" <?= selected($edit['material_id']??'', $item['id']) ?>><?= e($item['title']) ?></option><?php endforeach; ?></select></div><div class="form-group full"><label>Materi yang benar-benar terlaksana *</label><textarea class="form-control" name="actual_material" required><?= e($edit['actual_material']??'') ?></textarea></div><div class="form-group"><label>Metode pembelajaran</label><input class="form-control" name="learning_method" placeholder="Diskusi, demonstrasi, PBL..." value="<?= e($edit['learning_method']??'') ?>"></div><div class="form-group"><label>Aktivitas kelas</label><input class="form-control" name="class_activity" value="<?= e($edit['class_activity']??'') ?>"></div><div class="form-group"><label>Siswa hadir</label><input class="form-control" type="number" min="0" name="students_present" value="<?= e((string)($edit['students_present']??0)) ?>"></div><div class="form-group"><label>Siswa tidak hadir</label><input class="form-control" type="number" min="0" name="students_absent" value="<?= e((string)($edit['students_absent']??0)) ?>"></div><div class="form-group full"><label>Kendala pembelajaran</label><textarea class="form-control" name="obstacles"><?= e($edit['obstacles']??'') ?></textarea></div><div class="form-group full"><label>Respons siswa</label><textarea class="form-control" name="student_response"><?= e($edit['student_response']??'') ?></textarea></div><div class="form-group full"><label>Rencana tindak lanjut</label><textarea class="form-control" name="follow_up"><?= e($edit['follow_up']??'') ?></textarea></div><div class="form-group full"><label>Refleksi pengajar</label><textarea class="form-control" name="reflection"><?= e($edit['reflection']??'') ?></textarea></div></div><div class="form-actions"><a class="btn btn-secondary" href="<?= url('journals') ?>">Batal</a><button class="btn btn-primary">Simpan jurnal</button></div></form></div></section><?php endif; ?>
<section class="card mt-3"><div class="card-header"><div><h2>Riwayat jurnal</h2><p><?= count($journals) ?> jurnal tersimpan</p></div><div class="search-box"><?= icon('search',17) ?><input class="form-control" placeholder="Cari jurnal..." data-filter-table="#journal-table"></div></div><div class="table-wrap"><table class="data-table" id="journal-table"><thead><tr><th>Pertemuan</th><th>Materi terlaksana</th><th>Kehadiran</th><th>Tindak lanjut</th><th></th></tr></thead><tbody><?php foreach($journals as $item): ?><tr><td><strong><?= e($item['subject_name'].' • '.$item['class_name']) ?></strong><div class="muted text-sm"><?= e(indo_day($item['schedule_date']).', '.format_date($item['schedule_date']).' '.substr($item['start_time'],0,5)) ?></div></td><td><div class="truncate"><?= e($item['actual_material']) ?></div><div class="muted text-sm"><?= e($item['learning_method']?:'-') ?></div></td><td><?= (int)$item['students_present'] ?> hadir<div class="muted text-sm"><?= (int)$item['students_absent'] ?> tidak hadir</div></td><td class="truncate"><?= e($item['follow_up']?:'-') ?></td><td><div class="actions"><a class="btn btn-secondary btn-sm" href="<?= url('journals',['edit'=>$item['id']]) ?>"><?= icon('edit',14) ?></a><form method="post" data-confirm="Hapus jurnal ini?"><?= csrf_field() ?><input type="hidden" name="action" value="delete_journal"><input type="hidden" name="id" value="<?= $item['id'] ?>"><button class="btn btn-danger btn-sm"><?= icon('trash',14) ?></button></form></div></td></tr><?php endforeach; ?><?php if(!$journals): ?><tr><td colspan="5"><div class="empty-state"><h3>Belum ada jurnal</h3><p>Isi jurnal setelah mengajar agar progres pelaksanaan dapat ditelusuri.</p></div></td></tr><?php endif; ?></tbody></table></div></section>
